pgTable("consent_records", {
  id: uuid("id").primaryKey().defaultRandom(),

  // Subject
  subjectType: varchar("subject_type", { length: 50 }).notNull(),
  subjectId: uuid("subject_id").notNull(),

  // Organization
  organizationId: uuid("organization_id").notNull().references(() => organizations.id, { onDelete: "cascade" }),

  // Consent details
  purposeType: varchar("purpose_type", { length: 100 }).notNull(),
  // 'membership' | 'communications' | 'analytics' | 'marketing' | 'profiling'

  purposeDescription: text("purpose_description").notNull(),

  // Legal basis
  legalBasis: varchar("legal_basis", { length: 50 }).notNull(),
  // 'consent' | 'contract' | 'legal_obligation' | 'vital_interests' | 'public_task' | 'legitimate_interests'

  // Consent given
  consentGiven: boolean("consent_given").notNull(),
  consentMethod: varchar("consent_method", { length: 50 }),
  // 'explicit_opt_in' | 'checkbox' | 'electronic_signature' | 'physical_signature'

  consentText: text("consent_text"), // Exact text that was consented to
  consentVersion: varchar("consent_version", { length: 50 }),

  // Timing
  consentDate: timestamp("consent_date", { withTimezone: true }).notNull(),
  expiryDate: date("expiry_date"),

  // Withdrawal
  withdrawn: boolean("withdrawn").default(false),
  withdrawnAt: timestamp("withdrawn_at", { withTimezone: true }),
  withdrawalMethod: varchar("withdrawal_method", { length: 50 }),

  // Evidence
  ipAddress: varchar("ip_address", { length: 50 }),
  userAgent: text("user_agent"),
  evidenceUrl: text("evidence_url"), // URL to consent form screenshot/PDF

  // Audit trail
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),

  // Metadata
  metadata: jsonb("metadata").default(sql`'{}'::jsonb`),
})

pgTable('consent_records', {
  id: uuid('id').primaryKey().defaultRandom(),
  organizationId: uuid('organization_id')
    .notNull()
    .references(() => organizations.id, { onDelete: 'cascade' }),

  userId: varchar('user_id', { length: 255 }).notNull(),

  // Consent details
  consentType: varchar('consent_type', { length: 100 }).notNull(), // email_marketing, sms_alerts, etc.
  channel: consentChannelEnum('channel').notNull(),
  status: consentStatusEnum('status').notNull(), // granted, denied, revoked

  // Context
  method: varchar('method', { length: 50 }), // web_form, api, admin_import, etc.
  consentText: text('consent_text'), // Exact text user consented to
  ipAddress: varchar('ip_address', { length: 45 }),
  userAgent: text('user_agent'),

  // Expiration (for time-limited consent)
  expiresAt: timestamp('expires_at', { withTimezone: true }),

  // Metadata
  metadata: jsonb('metadata').default({}),

  // Immutable timestamp
  createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
}, (table) => ({
  orgIdx: index('idx_consent_records_org').on(table.organizationId),
  userIdx: index('idx_consent_records_user').on(table.userId),
  channelIdx: index('idx_consent_records_channel').on(table.channel),
  statusIdx: index('idx_consent_records_status').on(table.status),
  createdAtIdx: index('idx_consent_records_created').on(table.createdAt),
}))

pgTable("automation_rules", {
  id: uuid("id").primaryKey().defaultRandom(),
  name: varchar("name", { length: 255 }).notNull(),
  description: text("description"),
  status: varchar("status", { length: 20 }).notNull().default('draft'),
  priority: integer("priority").default(100),

  // Target entity
  targetEntity: varchar("target_entity", { length: 50 }).notNull(),
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  targetFilter: jsonb("target_filter").$type<Record<string, any>>(),

  // Trigger configuration
  triggerType: varchar("trigger_type", { length: 50 }).notNull(),
  triggerConfig: jsonb("trigger_config").$type<{
    event?: string;
    schedule?: string;
    condition?: string;
    webhookPath?: string;
  }>(),

  // Conditions (must all match for action to execute)
  conditions: jsonb("conditions").$type<Array<{
    field: string;
    operator: string;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    value: any;
  }>>(),

  // Actions to execute
  actions: jsonb("actions").$type<Array<{
    type: string;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    config: Record<string, any>;
    order: number;
  }>>(),

  // Execution limits
  maxExecutions: integer("max_executions"),
  executionsCount: integer("executions_count").default(0),
  lastExecutedAt: timestamp("last_executed_at", { withTimezone: true }),

  // Time windows
  activeFrom: timestamp("active_from", { withTimezone: true }),
  activeUntil: timestamp("active_until", { withTimezone: true }),
  timezone: varchar("timezone", { length: 50 }).default('UTC'),

  // Organization
  organizationId: varchar("organization_id", { length: 255 }).notNull(),

  // Metadata
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  createdBy: varchar("created_by", { length: 255 }),
}, (table) => [
  index("idx_automation_rules_status").on(table.status),
  index("idx_automation_rules_target").on(table.targetEntity),
  index("idx_automation_rules_org").on(table.organizationId),
  index("idx_automation_rules_priority").on(table.priority),
])

